-- 0006_maptexts.sql — miestne názvy (POPIS z VGI) + wms_sources register.
CREATE TABLE IF NOT EXISTS map_texts (id INTEGER PRIMARY KEY AUTOINCREMENT, dataset_id TEXT NOT NULL, lat REAL, lng REAL, txt TEXT NOT NULL, height REAL);
CREATE TABLE IF NOT EXISTS wms_sources (id INTEGER PRIMARY KEY AUTOINCREMENT, dataset_id TEXT, name TEXT NOT NULL, url TEXT NOT NULL, layers TEXT NOT NULL, format TEXT NOT NULL DEFAULT 'image/png', created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_mtexts_ds ON map_texts(dataset_id);
DELETE FROM map_texts;

